def band(a,b,skin,**kw):
    return dict(z0=round(a,4),z1=round(b,4),skin=skin,**kw)


def block(name,plan,a,b,skin='gray',**kw):
    return dict({'id':name,'plan':plan,'z0':a,'z1':b,'bands':[band(a,b,skin)],'roofTone':'roof'},**kw)


def opening(c,w,z,h=WIN_H):
    return dict(s0=round(c-w/2,4),s1=round(c+w/2,4),z0=round(z+SILL,4),
                z1=round(z+SILL+h,4),d=REVEAL,glass='glass',lit='room',tone='frame',
                mullion={'cols':[.5],'rows':[.72],'w':.045,'tone':'frame'})


def wall(skin,layout,rows=ROWS,a=BASE,b=MAIN):
    return band(a,b,skin,openings=[opening(c,w,z) for z in rows for c,w in layout])


def glazing(length,a,b,rows):
    # Four true window rows with a visible spandrel, not a single mirrored strip.
    ops=[]
    for z in rows:
        h=min(2.78,b-z-.20)
        ops.append(dict(s0=.08,s1=length-.08,z0=z+.12,z1=z+h,d=.045,
            glass='glass',lit='room',tone='frame',mullion={'cols':[.33,.66],'rows':[.22],
                                             'w':.065,'tone':'frame'}))
    return band(a,b,'dark',openings=ops)


def lounge(length):
    return band(MAIN,ROOF-.6,'wood',openings=[dict(s0=.28,s1=length-.28,
        z0=MAIN+.12,z1=ROOF-.72,d=LOUNGE_RECESS,glass='glass',lit='room',tone='wood',
        mullion={'cols':[.33,.66],'rows':[],'w':.075,'tone':'frame'})],
        _src='PHOTO: deeply recessed glazing behind open upper lounge; depth inferred.')


def region(bounds,bands):
    return dict(region=bounds,bands=bands)


def cylinder(mesh,caps,u,v,z,r=PLANT_RADIUS,h=PLANT_HEIGHT,segments=10):
    k=len(mesh['vertices'])
    for zz in (z,z+h):
        mesh['vertices'] += [[round(u+r*math.cos(i*2*math.pi/segments),4),
                             round(v+r*math.sin(i*2*math.pi/segments),4),zz]
                            for i in range(segments)]
    for i in range(segments):
        j=(i+1)%segments
        mesh['triangles'] += [[k+i,k+j,k+segments+j],[k+i,k+segments+j,k+segments+i]]
    c=len(caps['vertices']);caps['vertices'].append([u,v,z+h+.004])
    caps['vertices'] += [[round(u+r*.92*math.cos(i*2*math.pi/segments),4),
                         round(v+r*.92*math.sin(i*2*math.pi/segments),4),z+h+.004]
                        for i in range(segments)]
    caps['triangles'] += [[c,c+1+i,c+1+(i+1)%segments] for i in range(segments)]


def build():
    old=next(x for x in json.loads((ROOT/'data/neighborhood_apartments.json').read_text())['buildings'] if x['id']==ID)
    hole=copy.deepcopy(old['blocks'][0]['plan']['holes'])
    d={k:copy.deepcopy(old[k]) for k in ('id','name','footprint','frame')}
    d.update(address='2500 San Gabriel Street, Austin, TX',
      sources={
        'MAP':{'type':'map','source':'Existing neighborhood apartment outline, explicit local frame and courtyard hole',
               'date':'2026-10-11','confidence':'medium','supports':'Replacement outline, courtyard and approximate horizontal scale'},
        'PHOTO':{'type':'site photograph','confidence':'high',
                 'supports':'Four south/east front window rows, two-face glazed corner, top setback/terrace, material fields and visible roof plant; source joins private'},
        'OFFICIAL':{'type':'online photo','source':'https://www.noble2500.com/; https://www.markhartarch.com/noble-2500',
                    'accessDate':'2026-10-11','date':None,'confidence':'high',
                    'supports':'Two-storey glazed lobby, four residential rows, recessed balcony stack, cream corner fields and canopy'},
        'INFER':{'type':'inference','derivedFrom':['MAP','PHOTO','OFFICIAL'],'confidence':'low',
                 'supports':'Retained 24 m height, level metres, rectified plan, equipment count/positions, rear and courtyard openings'}},
      levels={'floors':[0,3.3]+ROWS+[MAIN,ROOF],
              '_src':'PHOTO/OFFICIAL: two base levels + four front residential rows + one recessed top level. INFER metric heights; not surveyed.'},
      colours={k:{'hex':v,'_src':'PHOTO midday appearance, albedo inferred; OFFICIAL corroborates material family, not dusk RGB.'} for k,v in COLORS.items()},
      skins={k:{'kind':'flat','field':k} for k in COLORS},
      balcony={'proj':1.2,'slabT':.16,'railH':1.05,'railT':.045},
      preserveRoof=False,preserveRoofscape=False,
      _review='Photo-led candidate, appearance acceptance pending. Source counts distinguished from approximate metric plan.',
      _open=['Mapped 24 m height retained; no independent survey height in this pass.',
             'Outer wall plan orthogonalized by up to about 1.5 m for supported overrides; geographic replacement ring and courtyard hole retained.',
             'North/west/courtyard opening rhythm inferred; no claim that all sides are photo-built.',
             'Condenser banks observed; individual count, size and plan positions inferred.',
             'Ground planting and objects hidden by trees have not been invented.'])
    d['materials']={}
    for field,scale,joint,tones,axis in [
        ('dark',[.16,3.45],'darkJoint',[['dark',1]],[1,0]),
        ('darkE',[.16,3.45],'darkJoint',[['darkE',1]],[0,1]),
        ('wood',[2.8,.18],'woodJoint',[['wood',3],['wood2',1]],[1,0]),
        ('gray',[3.4,.28],'grayJoint',[['gray',1]],[1,0]),
        ('stone',[.68,.29],'stoneJoint',[['stone',3],['stone2',1]],[1,0])]:
        d['materials'][field]={'scale':scale,'pattern':{'version':1,'tones':tones,
          'joint':{'width':.012,'tone':joint},'phase':[0,0],'axis':axis,'seed':71,'filter':[1,3]},
          '_src':'PHOTO/OFFICIAL material direction; INFER module width. Existing derivative-filtered wall material, no fine slat geometry.'}
    d['skins']['lobby']={'kind':'storefront','glass':'glass','frame':'frame','mullion':2.25,
        'mullionW':.095,'transom':.49,'fascia':.2,'fasciaTone':'bronze','plinth':.2,'reveal':.12}
    d['skins']['inferred']={'kind':'bays','field':'gray','windowRule':'all','bay':3.6,
        'window':{'w':1.8,'h':WIN_H,'sill':SILL},'glass':'glass','frame':'frame','reveal':REVEAL}
    plan={'ring':RING,'holes':hole}
    # The same hole survives both levels. No colored cap fills the court.
    base=block('glazed-base',plan,0,BASE,'stone',cap=False,
        overrides=[region([2,50.01,.99,1.01],[band(0,BASE,'lobby')]),
                   region([49.99,50.01,1,11],[band(0,BASE,'lobby')])],
        _src='OFFICIAL: lobby is two levels; PHOTO lower floors partly tree occluded. MAP court retained; rest base inferred.')
    main=block('four-row-residence',plan,BASE,MAIN,'inferred',parapet=.8,
        parapetTone='dark',parapetSides=['9','0'],
        _src='PHOTO/OFFICIAL: four residential rows below one recessed top level. MAP rectified plan; original courtyard retained.')
    main['overrides']=[]
    for a,b,skin,layout in SOUTH_REGIONS:
        bd=wall(skin,layout)
        if a==30:
            bd=band(BASE,MAIN,'dark',floors=ROWS,
                balconies=[{'s0':.22,'s1':b-a-.22,'inset':1.45,'insetTone':'wood',
                            'railTone':'rail','lift':0}],
                openings=[dict(s0=.5,s1=b-a-.5,z0=z+.1,z1=z+2.72,d=1.47,glass='glass',lit='room',tone='dark') for z in ROWS])
        elif a==43:bd=glazing(b-a,BASE,MAIN,ROWS)
        main['overrides'].append(region([a,b,.99,1.01],[bd]))
    # East front: corner glass / pale vertical field / glass / dark punctured edge.
    for a,b,skin,kind in [(1,4.2,'darkE','glass'),(4.2,6.0,'cream','solid'),
                           (6.0,9.4,'darkE','glass'),(9.4,11,'darkE','slit')]:
        if kind=='glass':bd=glazing(b-a,BASE,MAIN,ROWS)
        elif kind=='slit':bd=wall(skin,[((b-a)/2,.8)])
        else:bd=band(BASE,MAIN,skin)
        main['overrides'].append(region([49.99,50.01,a,b],[bd]))
    # The indented east wing has two tall divided-window fields with dark hoods.
    main['faces']={'4':{'bands':[wall('gray',[(2.6,1.8),(6.6,2.35),(10.6,1.15),(14.6,2.35),(18,1.8)])]}}
    upper=block('recessed-upper-level',{'ring':UPPER,'holes':hole},MAIN,ROOF,'wood',
        parapet=.58,parapetTone='cream',
        bands=[wall('wood',[(c,1.6) for c in (3,7,11,15,19,23,27,31,35,39,43)],rows=[MAIN],a=MAIN,b=ROOF)],
        _src='PHOTO: single timber-clad upper floor, inset south terrace and corner lounge. INFER depth, exact openings and rear faces.')
    # Override default upper bands: front is brown; side/back panels are gray.
    upper['overrides']=[region([38,47,4.99,5.01],[lounge(9),band(ROOF-.6,ROOF,'wood')]),
                       region([46.99,47.01,5,11],[lounge(6),band(ROOF-.6,ROOF,'wood')]),
                       region([50.49,50.51,18.7,38],[wall('gray',[(3,2.2),(7,1.5),(11,2.2),(16,1.5)],rows=[MAIN],a=MAIN,b=ROOF)]),
                       region([0,50.51,37.99,38.01],[band(MAIN,ROOF,'inferred')])]
    d['blocks']=[base,main,upper]
    # Broad material cap/canopy shapes matter in the whole view; no invented slope.
    d['blocks'] += [block('corner-canopy-south',[29.7,50.6,.35,1.15],BASE-.30,BASE,'bronze',
                    _src='PHOTO/OFFICIAL: dark copper-toned canopy across south storefront; plan projection inferred.'),
                   block('corner-canopy-east',[49.9,50.65,1.15,11.6],BASE-.30,BASE,'bronze',
                    _src='PHOTO/OFFICIAL canopy turns the corner.'),
                   block('upper-lounge-canopy',[37.7,47.4,4.2,11.2],ROOF-.48,ROOF-.18,'bronze',
                    _src='PHOTO upper corner lounge canopy; inferred projection.'),
                   block('south-terrace-floor',[2,50,1.1,5.0],MAIN,MAIN+.06,'deck',
                    _src='PHOTO: visible narrow upper terrace behind front guard.'),
                   block('east-terrace-floor',[47,50,5,11],MAIN,MAIN+.06,'deck',
                    _src='PHOTO: terrace turns outside the upper glazed lounge.')]
    # Upper guard is open metal over an opaque parapet; three horizontal rails.
    for z in [MAIN+.83,MAIN+1.03]:
        d['blocks'].append(block('south-guard-'+str(z),[2.2,49.8,1.18,1.24],z,z+.035,'rail',minDetail=2,
            _src='PHOTO thin rails above upper terrace parapet; spacing inferred.'))
    # Four small privacy fins divide the long upper terrace, with clear gaps.
    for i,u in enumerate([14,24,32,37]):
        d['blocks'].append(block('terrace-divider-'+str(i),[u,u+.12,1.8,5],MAIN+.06,MAIN+1.8,'wood',
             _src='PHOTO timber privacy screens along upper terrace; positions approximated from ratios.'))
    for face,length in [('9',48),('0',10)]:
        # Sign lives on the two main outer faces, below the residence rather than roof.
        base.setdefault('faces',{})[face]={'bands':[band(0,BASE,'lobby',signs=[
            {'outline':SIGN_OUTLINE,'w':8.2,'h':.72,'s':length/2,'z0':BASE-.02,'depth':.07,'off':.04,'tone':'bronze'}])]}
    # Cylindrical condensers, not solid cuboid rows. No fan-blade shimmer.
    mesh={'id':'roof-condenser-casings','tone':'plant','vertices':[],'triangles':[],
          '_src':'PHOTO: individual cylindrical condensers in banks. INFER grid counts and positions.'}
    caps={'id':'roof-condenser-tops','tone':'plantTop','vertices':[],'triangles':[],
          '_src':'PHOTO dark circular tops; no unobserved fan blades.'}
    for a,b,c,e,nu,nv in PLANT_BANKS:
        for i in range(nu):
            for j in range(nv):
                cylinder(mesh,caps,round(a+(b-a)*i/max(1,nu-1),4),round(c+(e-c)*j/max(1,nv-1),4),ROOF+.04)
    d['detailMeshes']=[mesh,caps]
    d['_counts']={'frontResidentialRows':4,'glazedBaseLevels':2,'setbackTopLevels':1,
                  'frontRecessedBalconyStacks':1,'terracePrivacyScreens':4,
                  'roofCondenserBanks':len(PLANT_BANKS),'roofCondenserUnits':sum(x[4]*x[5] for x in PLANT_BANKS),
                  '_src':'Rows/levels/one balcony stack observed. Equipment count and exact privacy-screen positions inferred, not a surveyed inventory.'}
    validate(d)
    return d


def validate(d):
    assert len(ROWS)==4 and len(set(ROWS))==4
    assert d['blocks'][0]['plan']['holes']==d['blocks'][1]['plan']['holes']==d['blocks'][2]['plan']['holes']
    for b in d['blocks']:
        assert b['z1']>b['z0'] and 0<=b['z0']<26 and b['z1']<26
        p=b['plan'];pts=(p['ring'] if isinstance(p,dict) else [[p[0],p[2]],[p[1],p[3]]])
        assert all(-.1<=u<=51 and -.1<=v<=39.3 for u,v in pts),b['id']
        for bd in b['bands']:
            assert bd['z1']>bd['z0']
        bands=[bd for f in b.get('faces',{}).values() if f for bd in f.get('bands',[])]
        bands += [bd for o in b.get('overrides',[]) for bd in o['bands']]
        for bd in bands:
            for o in bd.get('openings',[]):
                assert o['s1']>o['s0'] and o['z1']>o['z0'] and o['z0']>=b['z0']-.01 and o['z1']<=b['z1']+.01
    for mesh in d['detailMeshes']:
        assert all(len(p)==3 and all(math.isfinite(x) for x in p) for p in mesh['vertices'])
        assert all(len(t)==3 and min(t)>=0 and max(t)<len(mesh['vertices']) for t in mesh['triangles'])
    assert sum(len(m['triangles']) for m in d['detailMeshes'])<4000


if __name__=='__main__':
    data=build()
    deduplicate_detail_meshes(data)
    text=json.dumps(data,separators=(',',':'),ensure_ascii=False)
    OUT.write_text(text)
    print(f'{OUT.name}: {len(data["blocks"])} blocks, {data["_counts"]}; SHA256 {hashlib.sha256(text.encode()).hexdigest()}')
